// Generates the client's wire types from the session API contract
// (ADR 0059). With --check, fails when the committed types are stale.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const contract = new URL("../../../api/kit-session.openapi.json", import.meta.url);
const output = fileURLToPath(new URL("../src/api/schema.ts", import.meta.url));

const header = `// Generated by scripts/generate-api.ts from api/kit-session.openapi.json.
// Do not edit; run \`bun run generate:api\`.
`;

const ast = await openapiTS(contract, { exportType: true, enum: false, alphabetize: true });
const generated = header + astToString(ast);

if (process.argv.includes("--check")) {
  const committed = await readFile(output, "utf8").catch(() => "");
  if (committed !== generated) {
    console.error("apps/web/src/api/schema.ts is stale; run `bun run generate:api` in apps/web.");
    process.exit(1);
  }
  console.log("API types are current.");
} else {
  await writeFile(output, generated);
  console.log(`Wrote ${output}`);
}
